	gold:    { primary: '#ffcc00', accent: '#886600', bg: '#111100', enemy: '#ff4488', diamond: '#00ffcc' },
};

const ACH_DEF: [string, string, string][] = [
	['first_crush', 'First Crush', 'Crush your first Sno-Bee'],
