	score = 0; lives = 3; wave = 1; combo = 0; comboTimer = 0;
	pushCount = 0; totalCrushes = 0; totalStuns = 0; totalDiamondAligns = 0;
	phase: GamePhase = GamePhase.MENU;
	mode: GameMode = GameMode.ARCADE;
