					this.enemyMeshes[i].position.y = 0.4 + Math.sin(Date.now() * 0.02) * 0.05;
					const mat = this.enemyMeshes[i].material as MeshStandardMaterial;
					mat.opacity = 0.5 + Math.sin(Date.now() * 0.01) * 0.3;
