import { createSystem, World, InputComponent } from '@iwsdk/core';
import { gameState, GameSystem } from './game-system';
import { Direction, GamePhase } from './game-state';

export class InputSystem extends createSystem({}) {
	private world!: World;
	private gameSystem!: GameSystem;
	private keys: Set<string> = new Set();
	private moveRepeatTimer = 0;
	private lastDir: Direction | null = null;

	init() {
		this.world = (this as any).world;
		this.gameSystem = this.world.getSystem(GameSystem)!;
		if (typeof document !== 'undefined') {
			document.addEventListener('keydown', (e) => {
				this.keys.add(e.key.toLowerCase());
				this.handleKeyDown(e.key.toLowerCase());
			});
			document.addEventListener('keyup', (e) => {
				this.keys.delete(e.key.toLowerCase());
				if (this.lastDir !== null) {
					const dirKeys: Record<string, Direction> = {
						'arrowup': Direction.UP, 'w': Direction.UP,
						'arrowdown': Direction.DOWN, 's': Direction.DOWN,
						'arrowleft': Direction.LEFT, 'a': Direction.LEFT,
						'arrowright': Direction.RIGHT, 'd': Direction.RIGHT,
					};
					if (dirKeys[e.key.toLowerCase()] === this.lastDir) this.lastDir = null;
				}
			});
		}
	}

	private handleKeyDown(key: string) {
		if (gameState.phase === GamePhase.PLAYING) {
			const dirKeys: Record<string, Direction> = {
				'arrowup': Direction.UP, 'w': Direction.UP,
				'arrowdown': Direction.DOWN, 's': Direction.DOWN,
				'arrowleft': Direction.LEFT, 'a': Direction.LEFT,
				'arrowright': Direction.RIGHT, 'd': Direction.RIGHT,
			};
			if (dirKeys[key] !== undefined) {
				this.gameSystem.tryMove(dirKeys[key]);
				this.lastDir = dirKeys[key];
				this.moveRepeatTimer = 0.2;
			}
			if (key === 'escape' || key === 'p') {
				gameState.phase = GamePhase.PAUSED;
			}
		} else if (gameState.phase === GamePhase.PAUSED) {
			if (key === 'escape' || key === 'p') {
				gameState.phase = GamePhase.PLAYING;
			}
		}
	}

	update(delta: number) {
		// Keyboard repeat for held direction keys
		if (gameState.phase === GamePhase.PLAYING && this.lastDir !== null) {
			this.moveRepeatTimer -= delta;
			if (this.moveRepeatTimer <= 0) {
				this.moveRepeatTimer = 0.1;
				this.gameSystem.tryMove(this.lastDir);
			}
		}
		// VR controller input
		const input = this.world.input;
		if (!input) return;
		const axes = input.getAxesValues(InputComponent.ThumbstickLeft) || input.getAxesValues(InputComponent.Thumbstick);
		if (axes) {
			const threshold = 0.5;
			if (axes.y < -threshold && !gameState.playerMoving) this.gameSystem.tryMove(Direction.UP);
			else if (axes.y > threshold && !gameState.playerMoving) this.gameSystem.tryMove(Direction.DOWN);
			else if (axes.x < -threshold && !gameState.playerMoving) this.gameSystem.tryMove(Direction.LEFT);
			else if (axes.x > threshold && !gameState.playerMoving) this.gameSystem.tryMove(Direction.RIGHT);
		}
		// Trigger/A for action (could be used for special moves)
		if (input.getButtonDown(InputComponent.Trigger) || input.getButtonDown(InputComponent.ButtonA)) {
			if (gameState.phase === GamePhase.PLAYING) {
				// Trigger could be additional action in future
			}
		}
		// B for pause
		if (input.getButtonDown(InputComponent.ButtonB)) {
			if (gameState.phase === GamePhase.PLAYING) gameState.phase = GamePhase.PAUSED;
			else if (gameState.phase === GamePhase.PAUSED) gameState.phase = GamePhase.PLAYING;
		}
	}
}
